5,'       lastQTEHitboxX = hbPos\n                    lastQTEClick = 0\n                end\n\n                local now = tick()\n                local dtFrame = now - lastFrameTime\n                lastFrameTime = now\n\n                if dtFrame > 0.001 and dtFrame < 0.1 then\n                    local rawSpeed = (barPos - prevBarPos) / dtFrame\n                    prevBarPos = barPos\n                    if math.abs(rawSpeed) < 5 then\n                        currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3\n                    end\n                else\n                    prevBarPos = barPos\n                end\n\n                local lastInput = UserInputService:GetLastInputType()\n                local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025\n                local compensatedBarPos = barPos - (currentSpeed * latency)\n\n                local margin = hbSize * 0.15\n                local badOverlap = false\n                if badHitbox and badHitbox.Visible then\n                    local badLeft = badHitbox.Position.X.Scale - badHitbox.Size.X.Scale * badHitbox.AnchorPoint.X\n                    badOverlap = compensatedBarPos >= badLeft and compensatedBarPos <= badLeft + badHitbox.Size.X.Scale\n                end\n\n                if not badOverlap and compensatedBarPos >= hbPos + margin and compensatedBarPos <= hbPos + hbSize - margin then\n                    if tick() - lastQTEClick > 0.15 then\n                        lastQTEClick = tick()\n                        pressEnzoQTE()\n                    end\n                end\n            else\n                lastQTEHitboxX = nil\n                prevBarPos = 0\n                lastFrameTime = tick()\n                currentSpeed = 0\n            end\n        else\n            lastQTEHitboxX = nil\n            prevBarPos = 0\n            lastFrameTime = tick()\n            currentSpeed = 0\n        end\n    end\n\n    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then\n        local h = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n        local hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")\n        if h and hum then\n            local cameraLook = Camera.CFrame.LookVector\n            local move = hum.MoveDirection\n            local horizontal = Vector3.new(move.X, 0, move.Z)\n            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)\n            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)\n            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)\n            if look.Magnitude > 0.01 then\n                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)\n            end\n        end\n    end\n\n    if MiscFlags.FullBright then\n        if not NexusState.fullBrightApplied then\n            Lighting.Ambient = Color3.new(1,1,1)\n            Lighting.ColorShift_Bottom = Color3.new(1,1,1)\n            Lighting.ColorShift_Top = Color3.new(1,1,1)\n            Lighting.Brightness = 2\n            Lighting.OutdoorAmbient = Color3.new(1,1,1)\n            NexusState.fullBrightApplied = true\n        end\n    else\n        if NexusState.fullBrightApplied then\n            NexusState.fullBrightApplied = false\n        end\n    end\nend\n\nruntimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)\n    if not alive() then return end\n    pcall(updateFrameLogic, dt)\nend)\n\n-- ============================================================\n-- ===== PREPARE GLOBALS FOR THE CHUNKS =====\n-- ============================================================\n_G.RunService = RunService\n_G.LocalPlayer = LocalPlayer\n_G.VirtualUser = VirtualUser\n_G.UserInputService = UserInputService\n_G.Events = Events\n_G.MiscFlags = MiscFlags\n_G.alive = alive\n_G.runtimeEnv = runtimeEnv\n_G.Players = Players\n_G.Workspace = Workspace\n_G.Lighting = Lighting\n_G.NexusState = NexusState\n_G.Fishing = Fishing\n\n-- ===== LIVE ANTI-AFK (main chunk; fires only on real Idled, never steals controller) =====\ndo\n    local function nexusNudgeInput()\n        if Fishing and Fishing.Flags and not Fishing.Flags.AntiAFK then return end\n        local moving = false\n        pcall(function()\n            local char = LocalPlayer.Character\n            local hum = char and char:FindFirstChildOfClass("Humanoid")\n            local md = hum and hum.MoveDirection\n            if md and (math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05) then moving = true end\n        end)\n        if moving then return end\n        pcall(function()\n            if Events and Events:FindFirstChild("AFK") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser and workspace.CurrentCamera then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n    pcall(function()\n        if runtimeEnv.AntiAFKConnection then runtimeEnv.AntiAFKConnection:Disconnect() end\n    end)\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        nexusNudgeInput()\n    end)\nend\n\n-- ===== RUN THE EXTRA CHUNKS =====\nif _G.codetorun then loadstring(_G.codetorun)() end\nif _G.codes then loadstring(_G.codes)() end\n\n-- ===== SERVER HOP TAB =====\ndo\n    local ServerHopTab = Window:CreateTab("Server Hop")\n    local Section = ServerHopTab:CreateSection("List Server Hop")\n    NexusState.serverHopApiBase = NexusState.serverHopApiBase or "http://103.28.35.190:8000"\n    NexusState.serverHopApiKey = NexusState.serverHopApiKey or ""\n    NexusState.serverHopCategory = NexusState.serverHopCategory or "Taoist"\n    NexusState.serverHopBusy = false\n    NexusState.serverHopGeneration = 0\n    NexusState.serverHopRows = {}\n    local categories = {"Taoist", "Maoshan", "VermilionBird", "Weather"}\n    local statusHandle\n    local refresh\n    local function api(path, method, body)\n        local fn=(syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n        if type(fn)~="function" then return nil,"HTTP unavailable" end\n        local ok,res=pcall(fn,{Url=NexusState.serverHopApiBase:gsub("/$","")..path,Method=method or "GET",Timeout=10,Headers={["Content-Type"]="application/json",["X-API-Key"]=NexusState.serverHopApiKey or ""},Body=body})\n        if not ok or not res then return nil,"Relay request failed" end\n        local code=tonumber(res.StatusCode or res.Status); if not code or code<200 or code>=300 then return nil,"Relay HTTP "..tostring(code or "error") end\n        local body=res.Body or res.body; local good,data=pcall(function() return Services.HttpService:JSONDecode(body) end)\n        if not good or type(data)~="table" then return nil,"Invalid relay response" end\n        return data\n    end\n    local function currentWeather()\n        local result="Clear"\n        pcall(function()\n            local playerGui=LocalPlayer:FindFirstChild("PlayerGui")\n            local main=playerGui and playerGui:FindFirstChild("MainGui")\n            local info=main and main:FindFirstChild("Info")\n            local details=info and info:FindFirstChild("Info")\n            local weather=details and details:FindFirstChild("Weather")\n            local value=weather and weather:FindFirstChild("Value")\n            if value then\n                local raw=value:IsA("TextLabel") and value.Text or value.Value\n                result=tostring(raw or "Clear"):gsub("Weather:%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")\n            end\n        end)\n        return result\n    end\n    local function publishHeartbeat()\n        local payload=Services.HttpService:JSONEncode({job_id=game.JobId,place_id=game.PlaceId,playing=#Players:GetPlayers(),max_players=Players.MaxPlayers,attributes={weather=currentWeather()},source="nexus_noguard"})\n        return api("/v1/servers/update","POST",payload) ~= nil\n    end\n    local function kind(s)\n        local a=s.attributes or {}; local t=string.lower(tostring(a.event or "").." "..tostring(a.boss or "").." "..tostring(a.npc or ""))\n        if t:find("vermilion") then return "VermilionBird" end; if t:find("taoist") then return "Taoist" end; if t:find("maoshan") then return "Maoshan" end; if a.weather and tostring(a.weather)~="" and string.lower(tostring(a.weather))~="clear" then return "Weather" end; return "Other"\n    end\n    local function clearRows() for _,h in ipairs(NexusState.serverHopRows) do pcall(function() if h and h._frame then h._frame:Destroy() end end) end; NexusState.serverHopRows={} end\n    local function setStatus(v) if statusHandle and statusHandle.Set then pcall(statusHandle.Set,statusHandle,v) end end\n    local function join(s)\n        local job=tostring(s.job_id or s.jobId or ""); if job=="" or job==game.JobId then setStatus(job==game.JobId and "Already in this server." or "No valid Job ID."); return end\n        local n=tonumber(s.playing) or 0; local m=tonumber(s.max_players or s.maxPlayers) or 0; if m>0 and n>=m then setStatus("Server is full."); return end\n        setStatus("Joining "..job:sub(1,8).."..."); local ok,err=pcall(function() Services.TeleportService:TeleportToPlaceInstance(game.PlaceId,job,LocalPlayer) end); if not ok then setStatus("Join failed: "..tostring(err)) end\n    end\n    local function render(list)\n        clearRows(); local shown=0\n        for _,s in ipairs(list or {}) do local k=kind(s); if k==NexusState.serverHopCategory then shown=shown+1; local job=tostring(s.job_id or s.jobId or ""); local n=tonumber(s.playing) or 0; local m=tonumber(s.max_players or s.maxPlayers) or 0; local h=Section:CreateButton({Name=string.format("%s | %d/%d | %s",k,n,m,job:sub(1,8)),Callback=function() join(s) end}); table.insert(NexusState.serverHopRows,h) end end\n        if shown==0 then local h=Section:CreateButton({Name=NexusState.serverHopCategory.." has no active server. Press Refresh.",Callback=function() refresh() end}); table.insert(NexusState.serverHopRows,h) end\n        setStatus(string.format("%d server(s) | %s",shown,NexusState.serverHopCategory))\n    end\n    refresh = function()\n        if NexusState.serverHopBusy then return end; NexusState.serverHopBusy=true; NexusState.serverHopGeneration=NexusState.serverHopGeneration+1; local gen=NexusState.serverHopGeneration; setStatus("Loading "..NexusState.serverHopCategory.." servers...")\n        task.spawn(function()\n            local heartbeatOk=publishHeartbeat()\n            local data,err=api(string.format("/v1/servers?place_id=%d",game.PlaceId))\n            if gen~=NexusState.serverHopGeneration or not alive() then return end\n            NexusState.serverHopBusy=false\n            if data and type(data.servers)=="table" then\n                NexusState.serverHopServers=data.servers\n                render(data.servers)\n                if not heartbeatOk then setStatus("Loaded list; heartbeat update failed.") end\n            else\n                clearRows()\n                setStatus(err or "Unable to load servers.")\n            end\n        end)\n    end\n    local dc={Name="Server Hop",Options=categories,Default=NexusState.serverHopCategory,Callback=function(v) NexusState.serverHopCategory=v; render(NexusState.serverHopServers or {}); refresh() end}\n    Cfg.register(Section:CreateDropdown(Cfg.wrap("Dropdown","Server Hop",dc)),"Dropdown","Server Hop",dc)\n    local sc={Name="Status",Default="Press Refresh to load servers.",Callback=function() end}; statusHandle=Cfg.register(Section:CreateTextbox(Cfg.wrap("Textbox","Server Hop Status",sc)),"Textbox","Server Hop Status",sc)\n    local rc={Name="Refresh Server List",Callback=refresh}; Cfg.register(Section:CreateButton(Cfg.wrap("Button","Refresh Server List",rc)\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "NPC Teleport", Message = "NPC not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "NPC Teleport", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "NPC Teleport", Message = "Teleported to " .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = "Sage Yijiu"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap("Dropdown", "Learn Skill NPC", {\n            Name = "Learn Skill NPC",\n            Options = {"Sage Yijiu"},\n            Default = "Sage Yijiu",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), "Dropdown", "Learn Skill NPC", {\n            Name = "Learn Skill NPC",\n            Options = {"Sage Yijiu"},\n            Default = "Sage Yijiu",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = "Teleport to selected NPC",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild("NPC") \n                    and workspace.NPC:FindFirstChild("LearnSkill") \n                    and workspace.NPC.LearnSkill:FindFirstChild("Sage Yijiu")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "Learn Skill", Message = "Sage Yijiu not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "Learn Skill", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "Learn Skill", Message = "Teleported to Sage Yijiu", Duration = 2 })\n            end\n        })\n        -- ===== SECRET RODS SECTION =====\n        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)\n        local function getSecretRodList()\n            local rods = {}\n            local secretRodFolder = workspace:FindFirstChild("SecretRod")\n            if not secretRodFolder then return rods end\n            \n            for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                    table.insert(rods, child.Name)\n                end\n            end\n            return rods\n        end\n        \n        local rodList = getSecretRodList()\n        if #rodList == 0 then\n            table.insert(rodList, "No Secret Rods found")\n        end\n        \n        local selectedRod = rodList[1]\n        \n        -- Dropdown\n        local rodDropdown = NpcSection:CreateDropdown({\n            Name = "Secret Rods",\n            Options = rodList,\n            Default = selectedRod,\n            Callback = function(value)\n                selectedRod = value\n            end\n        })\n        \n        -- Teleport button\n        NpcSection:CreateButton({\n            Name = "Teleport to selected Secret Rod",\n            Callback = function()\n                if not selectedRod or selectedRod == "No Secret Rods found" then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "No Secret Rod selected!", Duration = 2 })\n                    return\n                end\n                \n                local secretRodFolder = workspace:FindFirstChild("SecretRod")\n                if not secretRodFolder then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "SecretRod folder not found!", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "Secret Rod not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "Secret Rod", Message = "Teleported to " .. selectedRod, Duration = 2 })\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== SETTINGS TAB =====\n-- ============================================================\ndo\n    local SettingsTab = Window:CreateTab("Settings")\n\n    -- ===== CONFIG SECTION (save / load / auto-load / import-export) =====\n    do\n        local CfgUI = SettingsTab:CreateSection("Config")\n        local Cfg = runtimeEnv.NexusConfig\n\n        CfgUI:CreateButton({\n            Name = "Save Config",\n            Callback = function() Cfg.save() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Load Config",\n            Callback = function() Cfg.load() end,\n        })\n\n        CfgUI:CreateToggle({\n            Name = "Auto Load Config",\n            Default = false,\n            Callback = function(value)\n                if not (writefile and isfile) then\n                    NexusLib:Notify({ Title = "Config", Message = "This executor cannot save files.", Duration = 3 })\n                    return\n                end\n                if value then\n                    Cfg.save(Cfg.AUTO_FILE)\n                else\n                    pcall(function()\n                        if isfile(Cfg.AUTO_FILE) and delfile then delfile(Cfg.AUTO_FILE) end\n                    end)\n                end\n            end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Export Config (Copy Code)",\n            Callback = function() Cfg.exportCode() end,\n        })\n\n        local importBox = CfgUI:CreateTextbox({\n            Name = "Import Config Code",\n            Placeholder = "Paste code, then press Import",\n            Default = "",\n            Callback = function() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Import Config",\n            Callback = function()\n                local code = ""\n                pcall(function() code = importBox.Get() end)\n                Cfg.importCode(code)\n            end,\n        })\n    end\n    local CharSection = SettingsTab:CreateSection("Character")\n\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap("Textbox", "Walk Speed", { Name = "Walk Speed", Placeholder = "16", Default = "16", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })), "Textbox", "Walk Speed", { Name = "Walk Speed", Placeholder = "16", Default = "16", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })\n\n    local function startFly()\n        local c = LocalPlayer.Character\n        if not c or not c:FindFirstChild("HumanoidRootPart") then return end\n        if NexusState.flying then return end\n        if NexusState.bg then NexusState.bg:Destroy() end\n        if NexusState.bv then NexusState.bv:Destroy() end\n        local h = c.HumanoidRootPart\n        NexusState.bg = Instance.new("BodyGyro", h)\n        NexusState.bg.P = 9e4\n        NexusState.bg.maxTorque = Vector3.new(9e9,9e9,9e9)\n        NexusState.bg.cframe = h.CFrame\n        NexusState.bv = Instance.new("BodyVelocity", h)\n        NexusState.bv.velocity = Vector3.new(0,0,0)\n        NexusState.bv.maxForce = Vector3.new(9e9,9e9,9e9)\n        NexusState.flying = true\n        local humanoid = c:FindFirstChildOfClass("Humanoid")\n        if humanoid then humanoid.PlatformStand = true end\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect() end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect() end\n        NexusState.flyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)\n            if gameProcessed then return end\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = true end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = true end\n        end)\n        NexusState.flyInputEndConnection = UserInputService.InputEnded:Connect(function(input)\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = false end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = false end\n        end)\n    end\n\n    local function stopFly()\n        NexusState.flying = false\n        NexusState.flyKeys.Up, NexusState.flyKeys.Down = false, false\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect(); NexusState.flyInputConnection = nil end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect(); NexusState.flyInputEndConnection = nil end\n        if NexusState.bg then NexusState.bg:Destroy(); NexusState.bg = nil end\n        if NexusState.bv then NexusState.bv:Destroy(); NexusState.bv = nil end\n        local c = LocalPlayer.Character\