"\xB1|h\xECRH\x17\xA6[;L9\x9C\x19\xBD\xD7\x9D{\xE0:~^\xEAB",70895,"R,\x1Fh\xB2\x8D@\x02\x03Xl\x97\x99%-y<\xF6\xC6\xC2\xA7>\xF6\xC0",'0.25)\n        pcall(function()\n            Events.ChooseDialogueOption:FireServer("Ticket Quest Giver", 1, action, extraData)\n        end)\n        task.wait(0.2)\n        if origCF and root and root.Parent then\n            pcall(function() root.CFrame = origCF end)\n        end\n        return true\n    end\n\n    -- ===== AUTO CLAIM TICKET QUEST =====\n    do\n        local ClaimSection = QuestsTab:CreateSection("Auto Claim Ticket Quest")\n        local questTypes = {"Easy Quest", "Hard Quest"}\n        local selectedQuest = questTypes[1]\n\n        local function HasActiveQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false end\n            local quest = userData:FindFirstChild("Quest")\n            if not quest then return false end\n            local main = quest:FindFirstChild("Main")\n            if not main then return false end\n            for _, child in pairs(main:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then\n                    local name = child.Name\n                    if name == "Easy Ticket Quest" or name == "Hard Ticket Quest" then\n                        return true\n                    end\n                end\n            end\n            return false\n        end\n\n        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Quest Type", {\n            Name = "Select Quest Type",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })), "Dropdown", "Select Quest Type", {\n            Name = "Select Quest Type",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })\n\n        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap("Toggle", "Auto Claim Ticket Quest (Fast)", {\n            Name = "Auto Claim Ticket Quest (Fast)",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == "Easy Quest" then\n                                        selAction = "EasyAcceptQuest"\n                                    else\n                                        selAction = "HardAcceptQuest"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = "Quest",\n                                            Message = "Claimed " .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Claim Ticket Quest (Fast)", {\n            Name = "Auto Claim Ticket Quest (Fast)",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == "Easy Quest" then\n                                        selAction = "EasyAcceptQuest"\n                                    else\n                                        selAction = "HardAcceptQuest"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = "Quest",\n                                            Message = "Claimed " .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- ===== DAILY QUESTS =====\n    do\n        local DailySection = QuestsTab:CreateSection("Daily Quests")\n        local dailyRunning = false\n        local dailyThread = nil\n\n        local function teleportToIsland(island)\n            if not island then return false end\n            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n            if not hrp then return false end\n            local target = island.cframe.Position + Vector3.new(0, 5, 0)\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = CFrame.new(target)\n            return true\n        end\n\n        local function doDailyQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "User data not found!", Duration = 2 })\n                return\n            end\n            local dailyFolder = userData:FindFirstChild("Quest") and userData.Quest:FindFirstChild("Daily")\n            if not dailyFolder then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Daily quest folder not found!", Duration = 2 })\n                return\n            end\n            local questFolders = {}\n            for _, child in pairs(dailyFolder:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Folder") then\n                    table.insert(questFolders, child)\n                end\n            end\n            if #questFolders == 0 then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "No daily quests available!", Duration = 2 })\n                return\n            end\n            local selectedFolder = questFolders[math.random(1, #questFolders)]\n            local questId = selectedFolder.Name\n            local progression = selectedFolder:FindFirstChild("Progression")\n            local questType = selectedFolder:FindFirstChild("QuestType")\n            if not progression or not questType then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Missing Progression or QuestType in quest " .. questId, Duration = 2 })\n                return\n            end\n            local currentProgress = (typeof(progression) == "Instance" and progression:IsA("NumberValue")) and progression.Value or 0\n            local qType = (typeof(questType) == "Instance" and questType:IsA("StringValue")) and questType.Value or ""\n\n            NexusLib:Notify({\n                Title = "Daily Quest",\n                Message = "Selected quest " .. questId .. " | Type: " .. qType .. " | Progress: " .. currentProgress,\n                Duration = 4\n            })\n\n            if qType == "PlayTime" then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "PlayTime quest: just play for 30 minutes!", Duration = 3 })\n                return\n            end\n\n            if qType == "Fishing" then\n                local island = getRecommendedIsland()\n                if not island then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "No suitable island found!", Duration = 2 })\n                    return\n                end\n                if not teleportToIsland(island) then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Teleport failed!", Duration = 2 })\n                    return\n                end\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Fishing daily started on " .. island.name, Duration = 2 })\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild("Progression")\n                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then\n                        if newProgress.Value >= 100 then\n                            NexusLib:Notify({ Title = "Daily Quest", Message = "Fishing daily completed!", Duration = 3 })\n \n                else\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = "Gacha", Message = "Stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Gacha", {\n            Name = "Auto Gacha",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGachaRunning = value\n                if value then\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusState.autoGachaThread = task.spawn(function()\n                        while NexusState.autoGachaRunning do\n                            pcall(function()\n                                local ticketCount = GetTicketCount()\n                                local needed = tonumber(selectedAmount) or 1\n                                local crystalCount = GetCrystals()\n                                local canRoll = false\n                                if ticketCount >= needed then\n                                    canRoll = true\n                                else\n                                    local missing = needed - ticketCount\n                                    local crystalsNeeded = missing * 5\n                                    if crystalCount >= crystalsNeeded then\n                                        canRoll = true\n                                    else\n                                        NexusLib:Notify({\n                                            Title = "Gacha",\n                                            Message = "Not enough tickets/crystals! Need " .. crystalsNeeded .. " crystals (have " .. crystalCount .. "). Stopping.",\n                                            Duration = 4\n                                        })\n                                        NexusState.autoGachaRunning = false\n                                        return\n                                    end\n                                end\n                                if canRoll then\n                                    local isTen = (selectedAmount == "10")\n                                    Events.Gacha:FireServer(isTen, selectedBanner)\n                                    NexusLib:Notify({\n                                        Title = "Gacha",\n                                        Message = "Rolled " .. selectedAmount .. " ticket(s) on " .. selectedBanner,\n                                        Duration = 2\n                                    })\n                                end\n                            end)\n                            task.wait(2)\n                        end\n                    end)\n                else\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = "Gacha", Message = "Stopped", Duration = 2 })\n                end\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== EXCHANGE TAB =====\n-- ============================================================\ndo\n    local ExchangeTab = Window:CreateTab("Exchange")\n    local ExchangeSection = ExchangeTab:CreateSection("Exchange Items")\n\n    local exchangeAmount = 1\n    local exchangeType = "Trait Reroll"\n\n    Cfg.register(ExchangeSection:CreateTextbox(Cfg.wrap("Textbox", "Quantity", {\n        Name = "Quantity",\n        Placeholder = "1",\n        Default = "1",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })), "Textbox", "Quantity", {\n        Name = "Quantity",\n        Placeholder = "1",\n        Default = "1",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })\n\n    Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose an item", {\n        Name = "Choose an item",\n        Options = {"Trait Reroll", "EssenceOrb"},\n        Default = "Trait Reroll",\n        Callback = function(value) exchangeType = value end\n    })), "Dropdown", "Choose an item", {\n        Name = "Choose an item",\n        Options = {"Trait Reroll", "EssenceOrb"},\n        Default = "Trait Reroll",\n        Callback = function(value) exchangeType = value end\n    })\n\n    local exchangeMethodDropdown = Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap("Dropdown", "Exchange Method", {\n        Name = "Exchange Method",\n        Options = {"Instant", "Teleport"},\n        Default = NexusState.exchange.method or "Instant",\n        Callback = function(value) NexusState.exchange.method = value end\n    })), "Dropdown", "Exchange Method", {\n        Name = "Exchange Method",\n        Options = {"Instant", "Teleport"},\n        Default = NexusState.exchange.method or "Instant",\n        Callback = function(value) NexusState.exchange.method = value end\n    })\n\n    ExchangeSection:CreateButton({\n        Name = "Exchange now",\n        Callback = function()\n            local userId = LocalPlayer.UserId\n            local userData = Data:FindFirstChild(tostring(userId))\n            if not userData then\n                NexusLib:Notify({ Title = "Exchange", Message = "Player data not found!", Duration = 2 })\n                return\n            end\n            local crystal = userData:FindFirstChild("Crystal")\n            local cash = userData:FindFirstChild("Cash")\n            if not crystal or not cash then\n                NexusLib:Notify({ Title = "Exchange", Message = "Crystal or Cash not found!", Duration = 2 })\n                return\n            end\n            local qty = exchangeAmount\n            local crystalNeed = qty * 5\n            local cashNeed = qty * 5000000\n            if crystal.Value < crystalNeed then\n                NexusLib:Notify({ Title = "Exchange", Message = "Not enough Crystals! Need " .. crystalNeed .. ", have " .. crystal.Value, Duration = 3 })\n                return\n            end\n            if cash.Value < cashNeed then\n                NexusLib:Notify({ Title = "Exchange", Message = "Not enough Cash! Need " .. cashNeed .. ", have " .. cash.Value, Duration = 3 })\n                return\n            end\n\n            NexusState.exchange.teleported = false\n            NexusState.exchange.oldPosition = nil\n            if NexusState.exchange.method == "Teleport" then\n                local npc = Workspace:FindFirstChild("NPC")\n                if npc then\n                    local func = npc:FindFirstChild("Function")\n                    if func then\n                        local nanjiang = func:FindFirstChild("Nanjiang")\n                        if typeof(nanjiang) == "Instance" and nanjiang:IsA("Model") then\n                            local hrp = nanjiang:FindFirstChild("HumanoidRootPart")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild("HumanoidRootPart")\n                                    if root then\n                                        NexusState.exchange.oldPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        NexusState.exchange.teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                if not NexusState.exchange.teleported then\n                    NexusLib:Notify({ Title = "Exchange", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })\n                end\n            end\n\n            local success, err = pcall(function()\n                Events.Exchange:FireServer(exchangeType, qty)\n            end)\n\n            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then\n                task.wait(0.2)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild("HumanoidRootPart")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)\n                        NexusState.exchange.oldPosition = nil\n                        NexusState.exchange.teleported = false\n                    end\n                end\n            end\n\n            if success then\n                NexusLib:Notify({ Title = "Exchange", Message = "Exchanged " .. qty .. " " .. exchangeType .. "!", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Exchange", Message = "Exchange failed: " .. tostring(err), Duration = 2 })\n            end\n        end\n    })\nend\n\n-- ============================================================\n-- ===== QUESTS TAB =====\n-- ============================================================\ndo\n    local QuestsTab = Window:CreateTab("Quests")\n\n    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.\n    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.\n    NexusState.ticketLastFire = NexusState.ticketLastFire or 0\n    NexusState.ticketFailCount = NexusState.ticketFailCount or 0\n    local function ticketGoFire(action)\n        if _G and _G.Events then\n            local sd = _G.Events:FindFirstChild("StartDialogue")\n            local cd = _G.Events:FindFirstChild("ChooseDialogueOption")\n            if not sd or not cd then return false end\n        end\n        local giver = nil\n        pcall(function()\n            local npc = Workspace:FindFirstChild("NPC")\n            local npcFunc = npc and npc:FindFirstChild("Function")\n            giver = npcFunc and npcFunc:FindFirstChild("Ticket Quest Giver")\n        end)\n        if not giver then return false end\n        local extraData = { giver }\n        local charNow = LocalPlayer.Character\n        local root = charNow and charNow:FindFirstChild("HumanoidRootPart")\n        local giverPos = nil\n        pcall(function()\n            if typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("Model") then\n                local hrp = giver:FindFirstChild("HumanoidRootPart")\n                if hrp then\n                    giverPos = hrp.Position\n                elseif giver.PrimaryPart then\n                    giverPos = giver.PrimaryPart.Position\n                else\n                    giverPos = giver:GetPivot().Position\n                end\n            elseif typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("BasePart") then\n                giverPos = giver.Position\n            end\n        end)\n        local origCF = root and root.CFrame\n        if root and giverPos then\n            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)\n            task.wait(0.45)\n        end\n        pcall(function()\n            Events.StartDialogue:FireServer("Ticket Quest Giver", giver)\n        end)\n        task.wait(thod = "POST",\n                Headers = { ["Content-Type"] = "application/json" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function watchEnzoReady()\n        local wasReady = false\n        while alive() do\n            local ready = false\n            pcall(function()\n                local root = Workspace:FindFirstChild("Bosses") or Workspace:FindFirstChild("Boss") or Workspace:FindFirstChild("NPC")\n                local enzo = root and root:FindFirstChild("Enzo", true)\n                if enzo then\n                    local cooldown = tonumber(enzo:GetAttribute("Cooldown")) or tonumber(enzo:GetAttribute("CooldownRemaining"))\n                    local endsAt = tonumber(enzo:GetAttribute("CooldownEnd"))\n                    ready = enzo:GetAttribute("CanAttack") == true or enzo:GetAttribute("Ready") == true or (cooldown and cooldown <= 0) or (endsAt and endsAt <= os.clock())\n                end\n            end)\n            if ready and not wasReady then sendServerEvent("Enzo Ready", { boss = "Enzo", ready = true }) end\n            wasReady = ready\n            task.wait(0.5)\n        end\n    end\n\n    local function sendSpiritWebhook()\n        sendServerEvent("SPIRIT", { npc = "God" })\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild("PlayerGui") and lp.PlayerGui:FindFirstChild("MainGui")\n        if mg then\n            local info = mg:FindFirstChild("Info")\n            if info then\n                local infoFrame = info:FindFirstChild("Info")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild("Weather")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild("Value")\n                        if val and typeof(val) == "Instance" then\n                            local text = (typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value)\n                            return text:gsub("Weather:%s*", "")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild("NPC")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist or ScanVermilionBird) and collectNpcModels() or {}\n\n        if ScanVermilionBird then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    local name = typeof(v) == "Instance" and v.Name:lower() or ""\n                    if typeof(v) == "Instance" and v:IsA("Model") and name:find("vermilion") and name:find("bird") and v:FindFirstChild("HumanoidRootPart") then found = true break end\n                end\n            end)\n            if found and not NexusState.LastVermilionBird then NexusState.LastVermilionBird = true; sendServerEvent("VermilionBird", { npc = "VermilionBird" }) elseif not found then NexusState.LastVermilionBird = false end\n        end\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == "Instance" and v:IsA("Model") and (string.find(v.Name:lower(), "maoshan") or string.find(v.Name:lower(), "merchant")) and v:FindFirstChild("HumanoidRootPart") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendServerEvent("Maoshan NPC", { npc = "Maoshan" })\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == "Instance" and v:IsA("Model") and string.find(v.Name:lower(), "taoist") and v:FindFirstChild("HumanoidRootPart") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendServerEvent("Taoist NPC", { npc = "Taoist" })\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild("NPC")\n                if npcF and npcF:FindFirstChild("God") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendServerEvent("SPIRIT", { npc = "God" })\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= "Clear" and uiWeather ~= "" then\n                current = uiWeather\n            else\n                for _, w in ipairs({"Rainy", "Thunderstorm", "Foggy", "Windy", "Snowy", "Blazing Sun"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= "clear" then\n            NexusState.LastWeather = current\n            sendServerEvent("Weather", { weather = current })\n        end\n    end\n\n    task.spawn(function()\n        task.spawn(watchEnzoReady)\n        local npcFolder = Workspace:WaitForChild("NPC", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild("PlayerGui", 30):WaitForChild("MainGui", 30)\n            local info = mg and mg:WaitForChild("Info", 15)\n            local infoFrame = info and info:WaitForChild("Info", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild("Weather", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild("Value", 15)\n            if val and typeof(val) == "Instance" then\n                local signal\n                if val:IsA("TextLabel") or val:IsA("TextButton") then signal = val:GetPropertyChangedSignal("Text") else signal = val:GetPropertyChangedSignal("Value") end\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n]]\n\n-- ============================================================\n-- ===== MAIN LOOPS (Boss Farm, Auto Sell, GUI QTE) =====\n-- ============================================================\nlocal function GetInventoryLimit()\n    local userFolder = GetPlayerData()\n    if not userFolder then return 0 end\n    local sum = 0\n    pcall(function()\n        for _, v in pairs(userFolder.Inventory:GetChildren()) do sum = sum + 1 end\n        for _, v in pairs(userFolder.Hotbar:GetChildren()) do sum = sum + v.Quantity.Value end\n    end)\n    return sum\nend\n\nlocal function IsInventoryFull()\n    local userFolder = GetPlayerData()\n    if not userFolder then return false end\n    local limit = 0\n    pcall(function() limit = userFolder.InventoryLimit.Value end)\n    return GetInventoryLimit() >= limit\nend\n\nlocal GuiService = Services.GuiService\nlocal nexusPanel = LocalPlayer.PlayerGui:FindFirstChild("NexusPanel")\n\nlocal function DisableNexusKeyboardActivation(object)\n    if typeof(object) == "Instance" and object:IsA("GuiObject") then\n        object.Selectable = false\n    end\nend\n\nif runtimeEnv.NexusSpaceGuardConnection then\n    runtimeEnv.NexusSpaceGuardConnection:Disconnect()\n    runtimeEnv.NexusSpaceGuardConnection = nil\nend\nif runtimeEnv.NexusSelectableGuardConnection then\n    runtimeEnv.NexusSelectableGuardConnection:Disconnect()\n    runtimeEnv.NexusSelectableGuardConnection = nil\nend\n\nif nexusPanel then\n    DisableNexusKeyboardActivation(nexusPanel)\n    for _, object in ipairs(nexusPanel:GetDescendants()) do\n        DisableNexusKeyboardActivation(object)\n    end\n    runtimeEnv.NexusSelectableGuardConnection = nexusPanel.DescendantAdded:Connect(function(object)\n        task.defer(DisableNexusKeyboardActivation, object)\n    end)\nend\n\nruntimeEnv.NexusSpaceGuardConnection = UserInputService.InputBegan:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Space then\n        local selected = GuiService.SelectedObject\n        if selected and nexusPanel and selected:IsDescendantOf(nexusPanel) then\n            GuiService.SelectedObject = nil\n        end\n    end\nend)\n\nlocal function bossFarmEnabled()\n    return Fishing.Flags.AutoFarmBoss or Fishing.Flags.AutoFarmSecretBoss\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = nil end\n    local infoFolder = ReplicatedStorage:FindFirstChild("Info")\n    if not infoFolder then return end\n    pcall(function()\n        local areaRarity = infoFolder:FindFirstChild("FishingAreaRarity")\n        if areaRarity then\n            local rarityData = require(areaRarity)\n            if type(rarityData) == "table" and type(rarityData["Secret Boss"]) == "table" then\n                for fishName in pairs(rarityData["Secret Boss"]) do\n                    local name = string.lower(tostring(fishName))\n                    NexusState.SecretBossNameSet[name] = true\n                    NexusState.BossNameSet[name] = true\n                end\n            end\n        end\n    end)\n    pcall(function()\n        local inventory = infoFolder:FindFirstChild("Inventory")\n        if inventory then\n            for _, module in pairs(inventory:GetChildren()) do\n                if typeof(module) == "Instance" and typeof(module) == "Instance" and module:IsA("ModuleScript") then\n                    local ok, itemData = pcall(require, module)\n                    if ok and type(itemData) == "table" then\n                        local name = string.lower(tostring(itemData.FishName or module.Name))\n                ',
