   ["Select Banner"] = "Pumili ng banner",\n            ["Select Player"] = "Pumili ng player",\n            ["Select Quest Type"] = "Pumili ng uri ng quest",\n            ["Select Skill"] = "Pumili ng skill",\n            ["Target Trait"] = "Target na trait",\n            ["Choose a Bait"] = "Pumili ng pain",\n            ["Choose an island"] = "Pumili ng isla",\n            ["Choose an item"] = "Pumili ng item",\n            ["Buy Amount"] = "Dami ng bibilhin",\n            ["Buy When Below"] = "Bumili kapag mas mababa",\n            ["Number of baits to craft"] = "Bilang ng pain na gagawin",\n            ["Quantity"] = "Dami",\n            ["Tickets per roll"] = "Ticket kada roll",\n            ["Fly Speed"] = "Bilis ng lipad",\n            ["Walk Speed"] = "Bilis ng lakad",\n            ["Risk hits/sec (1-200)"] = "Pindot/seg (1-200)",\n            ["Safe band (0.01-0.17)"] = "Ligtas na banda (0.01-0.17)",\n            ["Fake Username"] = "Pekeng username",\n            ["Fake Display Name"] = "Pekeng display name",\n            ["Name Of The Fish (Optional)"] = "Pangalan ng isda (opsyonal)",\n            ["Select bait for material farming"] = "Pumili ng pain para sa material farming",\n            ["Choose A Skill That Needs To Upgrade"] = "Pumili ng skill na i-upgrade",\n            ["Learn Skill NPC"] = "NPC para matuto ng skill",\n            ["Secret Rods"] = "Mga secret rod",\n            ["Misc NPCs"] = "Ibang NPC",\n            ["Players"] = "Mga player",\n            ["Allowed Weather Islands"] = "Mga pinapayagang isla ayon sa panahon",\n            ["Skills to press"] = "Skill na pipindutin",\n            ["Select fish to auto-favourite"] = "Pumili ng isda para sa auto-favourite",\n            ["Select Skills to Learn"] = "Pumili ng skill na matutunan",\n            ["Select 2 upgrade options"] = "Pumili ng 2 upgrade option",\n            ["Language"] = "Wika",\n            ["Language set to: "] = "Wika ay itinakda sa: ",\n        },\n    }\n\n    function I18n.getCurrentLanguage()\n        if NexusState.currentLanguage == "auto" then\n            return NexusState.detectedLanguage or "en"\n        end\n        return NexusState.currentLanguage or "en"\n    end\n\n    function I18n.get(key, fallback)\n        if not key or type(key) ~= "string" then return fallback or key end\n        local lang = I18n.getCurrentLanguage()\n        if lang == "en" then return fallback or key end\n        local dict = DICTIONARY[lang]\n        if dict and dict[key] then return dict[key] end\n        return fallback or key\n    end\n\n    local function translateObject(obj)\n        if not obj or typeof(obj) ~= "Instance" then return end\n        local lang = I18n.getCurrentLanguage()\n        if lang == "en" then return end\n        pcall(function()\n            if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then\n                local currentText = obj.Text\n                if not currentText or #currentText == 0 then return end\n                \n                local dict = DICTIONARY[lang]\n                \n                local orig = obj:GetAttribute("NexusOrigText")\n                if not orig or (dict and dict[currentText]) then\n                    orig = currentText\n                    obj:SetAttribute("NexusOrigText", orig)\n                end\n                \n                if orig and #orig > 0 then\n                    if lang == "en" then\n                        if obj.Text ~= orig then\n                            obj.Text = orig\n                        end\n                    else\n                        local trans = dict and dict[orig]\n                        if trans and obj.Text ~= trans then\n                            obj.Text = trans\n                        end\n                    end\n                end\n            end\n        end)\n    end\n\n    local function applyLanguageToGui(gui)\n        if not gui then return end\n        pcall(function()\n            for _, desc in ipairs(gui:GetDescendants()) do\n                translateObject(desc)\n            end\n        end)\n    end\n\n    function I18n.applyLanguage()\n      n return handle end\n        local kind = cfgKind(callKind)\n        local entry = ConfigSys.registry[name]\n        if not entry then\n            entry = { kind = kind }\n            ConfigSys.registry[name] = entry\n            table.insert(ConfigSys.ordered, name)\n        end\n        entry.kind = kind\n        -- The original Callback is captured here at registration time (from the\n        -- config table), because NexusLib handles do not expose it.\n        local cb = config and config.Callback or nil\n        if type(handle.Get) == "function" then\n            entry.get = function()\n                local ok, v = pcall(handle.Get)\n                return ok and v or nil\n            end\n        end\n        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set\n        -- calls set(v, false); dropdown/text Set only touch the label). After\n        -- Set we therefore re-fire the captured Callback so the hub state\n        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.\n        if type(handle.Set) == "function" then\n            entry.set = function(v)\n                pcall(handle.Set, handle, v)\n                if cb then\n                    task.spawn(cb, v)\n                end\n            end\n        elseif cb then\n            entry.set = function(v)\n                task.spawn(cb, v)\n            end\n        end\n        return handle\n    end\n\n    function ConfigSys.snapshot()\n        local out = {}\n        for name, entry in pairs(ConfigSys.registry) do\n            if entry.get then\n                local ok, v = pcall(entry.get)\n                if ok and v ~= nil then out[name] = v end\n            end\n        end\n        return out\n    end\n\n    function ConfigSys.apply(data)\n        if type(data) ~= "table" then return 0, 0 end\n        local okCount, missCount = 0, 0\n        for name, value in pairs(data) do\n            local entry = ConfigSys.registry[name]\n            if entry and entry.set then\n                local ok = pcall(entry.set, value)\n                if ok then okCount = okCount + 1 else missCount = missCount + 1 end\n            else\n                missCount = missCount + 1\n            end\n        end\n        return okCount, missCount\n    end\n\n    local function encode(data)\n        local HttpService = Services.HttpService\n        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)\n        return ok and s or nil\n    end\n\n    local function decode(s)\n        local HttpService = Services.HttpService\n        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)\n        if ok and type(data) == "table" then return data end\n        return nil\n    end\n\n    function ConfigSys.save(slot)\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then\n            NexusLib:Notify({ Title = "Config", Message = "Encode failed.", Duration = 3 })\n            return false\n        end\n        if not writefile then\n            NexusLib:Notify({ Title = "Config", Message = "This executor cannot save files.", Duration = 3 })\n            return false\n        end\n        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)\n        NexusLib:Notify({ Title = "Config", Message = ok and "Saved." or "Save failed.", Duration = 2 })\n        return ok\n    end\n\n    function ConfigSys.load(slot, silent)\n        if not (isfile and readfile) then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "This executor cannot read files.", Duration = 3 }) end\n            return false\n        end\n        local path = slot or ConfigSys.FILE\n        local has = false\n        pcall(function() has = isfile(path) end)\n        if not has then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "No saved config found.", Duration = 3 }) end\n            return false\n        end\n        local ok, raw = pcall(readfile, path)\n        if not ok or not raw then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "Read failed.", Duration = 3 }) end\n            return false\n        end\n        local wrap = decode(raw)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "Config file is corrupt.", Duration = 3 }) end\n            return false\n        end\n        -- Defer one frame so every tab has finished building its controls.\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            if not silent then\n                NexusLib:Notify({ Title = "Config", Message = "Loaded " .. okCount .. " settings" .. (missCount > 0 and " (" .. missCount .. " skipped)" or "") .. ".", Duration = 3 })\n            end\n        end)\n        return true\n    end\n\n    function ConfigSys.exportCode()\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then return nil end\n        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard\n        if clip then\n            pcall(clip, payload)\n            NexusLib:Notify({ Title = "Config", Message = "Config code copied to clipboard.", Duration = 3 })\n        else\n            NexusLib:Notify({ Title = "Config", Message = "Clipboard not supported on this executor.", Duration = 3 })\n        end\n        return payload\n    end\n\n    -- Import reads the clipboard when the executor exposes it; otherwise it falls\n    -- back to the textbox value typed/pasted by the user.\n    function ConfigSys.importCode(text)\n        local code = text\n        if (not code or code == "") and getclipboard then\n            pcall(function() code = getclipboard() end)\n        end\n        if not code or code == "" then\n            NexusLib:Notify({ Title = "Config", Message = "Paste a config code first.", Duration = 3 })\n            return false\n        end\n        local wrap = decode(code)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            NexusLib:Notify({ Title = "Config", Message = "Invalid config code.", Duration = 3 })\n            return false\n        end\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            NexusLib:Notify({ Title = "Config", Message = "Imported " .. okCount .. " settings" .. (missCount > 0 and " (" .. missCount .. " skipped)" or "") .. ".", Duration = 3 })\n        end)\n        return true\n    end\n\n    runtimeEnv.NexusConfig = ConfigSys\n    runtimeEnv.NexusCfgWrap = ConfigSys.wrap\n    ConfigSys._saving = false\nend\n\n\nlocal Cfg = runtimeEnv.NexusConfig\n\n-- ===== HOME TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage("dung UI: Session tab")\n    local HomeTab\n    do\n        runtimeEnv.NexusStage("dung UI: Session tab")\n        local ok, result = pcall(function() return Window:CreateTab("Session") end)\n        if not ok or result == nil then\n            runtimeEnv.NexusStage("UI Session tab failed")\n            runtimeEnv.NexusReport("Nexus UI failed", "CreateTab Session: " .. tostring(result))\n            return\n        end\n        HomeTab = result\n    end\n    HomeTab:CreateHeader({\n        Title = "Session overview",\n        Subtitle = "Live instruments for " .. LocalPlayer.Name\n    })\n    local statRow = HomeTab:CreateStatRow({\n        {Title = "LEVEL", Value = "...", Color = Color3.fromRGB(190, 158, 103)},\n        {Title = "BALANCE", Value = "...", Color = Color3.fromRGB(128, 159, 164)},\n        {Title = "SESSION", Value = "00:00:00", Color = Color3.fromRGB(139, 161, 142)}\n    })\n        -- Add 9 new stats\n    local statRow2 = HomeTab:CreateStatRow({\n        {Title = "ROD", Value = "...", Color = Color3.fromRGB(255, 215, 0)},\n        {Title = "CRYSTAL", Value = "...", Color = Color3.fromRGB(100, 200, 255)},\n        {Title = "ESSENCE", Value = "...", Color = Color3.fromRGB(255, 100, 200)}\n    })\n    local statRow3 = HomeTab:CreateStatRow({\n        {Title = "BAIT", Value = "...", Color = Color3.fromRGB(150, 255, 150)},\n        {Title = "FISH CAUGHT", Value = "...", Color = Color3.fromRGB(255, 200, 100)},\n        {Title = "TICKET", Value = "...", Color = Color3.fromRGB(200, 150, 255)}\n    })\n    local statRow4 = HomeTab:CreateStatRow({\n        {Title = "TRAIT REROLL", Value = "...", Color = Color3.fromRGB(255, 150, 150)},\n        {Title = "HEAVIEST FISH", Value = "...", Color = Color3.fromRGB(255, 180, 50)},\n        {Title = "BASE HP", Value = "...", Color = Color3.fromRGB(255, 100, 100)}\n    })\n    local hwid = "N/A"\n    pcall(function() hwid = Services.RbxAnalyticsService:GetClientId() end)\n    HomeTab:CreateFeaturedCard({\n        Tag = "Nexus",\n        Title = "Heavyweight Fishing",\n        Description = "Script by: Ngmankhoi,NgdepZaiNhatTG,Ethangcuto\\n\\nHWID: " .. string.sub(hwid, 1, 15) .. "...",\n        ButtonText = "DISCORD",\n        Callback = function()\n            NexusLib:Notify({ Title = "Discord", Message = "Link copied to clipboard!", Duration = 3 })\n            if setclipboard then setclipboard("https://discord.gg/QAdVUX2wCH") end\n        end\n    })\n\n        local scriptStartTime = time()\n        task.spawn(function()\n        -- Cache for every stat row\n        local cachedStat1, cachedStat2, cachedStat3\n        local cachedStat2_1, cachedStat2_2, cachedStat2_3\n        local cachedStat3_1, cachedStat3_2, cachedStat3_3\n        local cachedStat4_1\n        local cachedStat4_2, cachedStat4_3\n        local labelCache = {}\n\n        local function setStat(statFrame, text)\n            if not statFrame then return end\n            local lbl = labelCache[statFrame]\n            if not lbl or not lbl.Parent then\n                for _, child in ipairs(statFrame:GetDescendants()) do\n                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("TextLabel") and child.TextSize >= 18 then\n                        lbl = child\n                        labelCache[statFrame] = child\n                        break\n                    end\n                end\n            end\n            if lbl and lbl.Text ~= text then lbl.Text = text end\n        end\n\n        -- Stats fetch helper\n        local function getHomeStats()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return {} end\n            local stats = {}\n            local levelFolder = userData:FindFirstChild("Level")\n            stats.Level = levelFolder and levelFolder:FindFirstChild("Level") and tostring(levelFolder.Level.Value) or "N/A"\n            stats.Cash = userData:FindFirstChild("Cash") and tostring(userData.Cash.Value) or "N/A"\n            stats.Rod = userData:FindFirstChild("FishingRod") and tostring(userData.FishingRod.Value) or "N/A"\n            stats.Crystal = userData:FindFirstChild("Crystal") and tostring(userData.Crystal.Value) or "N/A"\n            stats.EssenceOrb = userData:FindFirstChild("EssenceOrb") and tostring(userData.EssenceOrb.Value) or "N/A"\n            stats.Bait = userData:FindFirstChild("EquippedBait") and tostring(userData.EquippedBait.Value) or "N/A"\n            stats.FishCaught = userData:FindFirstChild("FishCaught") and tostring(userData.FishCaught.Value) or "N/A"\n            stats.Ticket = userData:FindFirstChild("Ticket") and tostring(userData.Ticket.Value) or "N/A"\n            stats.TraitReroll = userData:FindFirstChild("Trait Reroll") and tostring(userData["Trait Reroll"].Value) or "N/A"\n            stats.HeaviestWeight = userData:FindFirstChild("HeaviestWeight") and tostring(userData.HeaviestWeight.Value) or "N/A"\n            stats.BaseHP = userData:FindFirstChild("BaseHP") and tostring(userData.BaseHP= function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Will equip rod if not holding", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Disabled", Duration = 2 })\n            end\n        end\n    })), "Toggle", "Auto Equip Fishing Rod (Slot 1)", {\n        Name = "Auto Equip Fishing Rod (Slot 1)",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Will equip rod if not holding", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Disabled", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        local ToggleHotbar = Events:FindFirstChild("ToggleHotbar")\n        if not ToggleHotbar then return end\n        while task.wait(1) do\n            if not alive() then break end\n            if MiscFlags.AutoEquipRod then\n                pcall(function()\n                    if not isHoldingFishingRod() then\n                        ToggleHotbar:InvokeServer("1", nil)\n                    end\n                end)\n            end\n        end\n    end)\n\n    EquipSection:CreateButton({\n        Name = "Equip Best Rod",\n        Callback = function()\n            local best = GetBestRod()\n            if best then\n                if EquipRod(best) then\n                    NexusLib:Notify({ Title = "Equip Rod", Message = "Equipped best rod: " .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = "Equip Rod", Message = "Failed to equip rod", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = "Equip Rod", Message = "No rod available", Duration = 2 })\n            end\n        end\n    })\n\n    EquipSection:CreateButton({\n        Name = "Equip Best Orb",\n        Callback = function()\n            local best = GetBestOrb()\n            if best then\n                if EquipOrb(best) then\n                    NexusLib:Notify({ Title = "Equip Orb", Message = "Equipped best orb: " .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = "Equip Orb", Message = "Failed to equip orb", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = "Equip Orb", Message = "No orb available", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        while task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild("EquippedBait")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or ""\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = "Auto Equip", Message = "Equipped best bait: " .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = "Nameless Octoparasite"\n        local RHY_LANES = { "A", "S", "D" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = "Safe",\n            RiskRate = 25,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            RiskThread = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild("Ocean")\n            if ocean then\n                local boss = ocean:FindFirstChild("Boss")\n                if boss then\n                    local fn = boss:FindFirstChild("FishName")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild("Fishes")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("BasePart") then return inst.CFrame end\n                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("Model") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA("BasePart", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = "Nameless", Message = "Cannot find " .. NAMELESS_NAME .. " in Workspace (boss not spawned yet?)", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = "Nameless", Message = "Found boss but could not get its position!", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = "Nameless", Message = "Character not found!", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = "Nameless", Message = "Teleported to " .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild("Button")\n                    if not btn then return false end\n                    if not (typeof(btn) == "Instance" and (btn:IsA("TextButton") or btn:IsA("ImageButton"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService("VirtualInputManager")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService("VirtualInputManager")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n                if ok and res then return true end\n                Rhy.Method = nil\n            end\n            for i, fn in ipairs(methods) do\n                local ok, res = pcall(fn)\n                if ok and res then\n                    Rhy.Method = i\n                    return true\n                end\n            end\n            return false\n        end\n\n        local function rhyGui()\n            local fishing = MainGui and MainGui:FindFirstChild("Fishing")\n            if not fishing then return nil, nil end\n            return fishing:FindFirstChild("Rhythm"), fishing\n        end\n\n        local function rhyUiActive()\n            local gui, fishing = rhyGui()\n            if not gui or not fishing then return false end\n            return gui.Visible == true and fishing.Visible == true\n        end\n\n        local function rhyMaxBand()\n            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02\n            if m < 0.01 then m = 0.01 end\n            return m\n        end\n\n        local function rhyScan(now)\n            local gui = rhyGui()\n            if not gui then return end\n            for _, lane in ipairs(RHY_LANES) do\n                local laneFrame = gui:FindFirstChild("Progression" .. lane)\n                if laneFrame then\n                    local barY = RHY_BAR_FALLBACK\n                    local barFrame = laneFrame:FindFirstChild("BarFrame")\n                    if barFrame then\n                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)\n                        if okB and type(y) == "number" then barY = y end\n                    end\n                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())\n                    local inWindow = 0\n                    for _, note in ipairs(laneFrame:GetChildren()) do\n                        if note.Name == "Note_FX" then\n                            local okP, y = pcall(function() return note.Position.Y.Scale end)\n                            if okP and type(y) == "number" then\n                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then\n                                    inWindow = inWindow + 1\n                                end\n                            end\n                        end\n                    end\n                    if inWindow > 5 then inWindow = 5 end\n                    for _ = 1, inWindow do\n                        if rhyPress(laneFrame, lane) then\n                            Rhy.Stats.hit = Rhy.Stats.hit + 1\n                        end\n                    end\n                end\n            end\n        end\n\n        local function rhyStartRisk()\n            if Rhy.RiskThread then return end\n            Rhy.RiskThread = task.spawn(function()\n                while alive() and Rhy.Enabled and Rhy.Mode == "Risk" and Rhy.Active do\n                    local rate = math.clamp(tonumber(Rhy.RiskRate) or 25, 1, 200)\n                    local burst = math.max(1, math.floor(rate / 20))\n                    for _ = 1, burst do\n                        pcall(function() Events.RhythmHit:FireServer("hit") end)\n                        Rhy.Stats.spam = Rhy.Stats.spam + 1\n                    end\n                    task.wait(burst / rate)\n                end\n                Rhy.RiskThread = nil\n            end)\n        end\n\n        if runtimeEnv.NexusRhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end\n        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end\n        ',
46289,96528.,"\xFA8\xF9\x9Ble4\x9F\x9F\x00/F\x1ED\xA4\xE1F\xC6R\xB3\xC8\x9Bt\xFBoL%8ou[-zqg&@IUk{=avgQ&",1090,'cal function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress()\n        if current and target and questName then\n            NexusState.ticketTargetCount = target\n            NexusState.ticketCurrentCount = current\n            NexusState.ticketQuestActive = true\n            if current >= target then\n                if not NexusState.ticketQuestClaimed then\n                    NexusLib:Notify({ Title = "Quest", Message = "Complete! Claiming reward...", Duration = 2 })\n                    -- TP to NPC, turn in with retries, chain next quest right away.\n                    local turnedIn = false\n                    for _ = 1, 5 do\n                        if ticketGoFire("Quest") then\n                            for _ = 1, 6 do\n                                task.wait(0.15)\n                                if not getCurrentQuestProgress() then\n                                    turnedIn = true\n                                    break\n                                end\n                            end\n                        end\n                        if turnedIn then break end\n                        task.wait(0.2)\n                    end\n                    if turnedIn then\n                        NexusState.ticketQuestClaimed = true\n                        NexusState.ticketLastFire = 0\n                        NexusState.ticketFailCount = 0\n                        NexusState.isDoingUseBaitQuest = false\n                        disableAllFishing()\n                        NexusState.ticketQuestActive = false\n                        NexusLib:Notify({ Title = "Quest", Message = "Turned in. Claim toggle takes next quest.", Duration = 3 })\n                    else\n                        NexusLib:Notify({ Title = "Quest", Message = "Turn-in failed, retrying...", Duration = 2 })\n                    end\n                end\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                NexusState.ticketQuestActive = false\n                return\n            end\n            NexusState.ticketQuestClaimed = false\n\n            -- Teleport to target island (manual choice wins)\n            local targetIsland = getTargetIsland()\n            if targetIsland then\n                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n                if hrp then\n                    local targetPos = targetIsland.cframe.Position + Vector3.new(0, 5, 0)\n                    if (hrp.Position - targetPos).Magnitude > 25 and (tick() - (NexusState.ticketLastTele or 0) > 3) then\n                        NexusState.ticketLastTele = tick()\n                        safeTeleport(hrp, CFrame.new(targetPos))\n                    end\n                end\n            end\n\n                        local need = string.lower(tostring(typ or "") .. " " .. tostring(NexusState.ticketObjectiveText or ""))\n            local function needHas(...)\n                for _, k in ipairs({...}) do\n                    if string.find(need, k, 1, true) then return true end\n                end\n                return false\n            end\n            NexusState.isDoingUseBaitQuest = false\n            -- Ticket pool: use bait / catch fish / heavy fish (1.5M) / use skill.\n            -- No boss quests here, so boss words inside fish names must not trigger boss farm.\n            if needHas("usebait", "use bait", "bait") then\n                NexusState.isDoingUseBaitQuest = true\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AnchorLock = true\n                Fishing.Flags.AutoSkill = true\n          