65535.,"if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end\n        if runtimeEnv.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end\n        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end\n\n        pcall(function()\n            local evStart = Events:FindFirstChild(\"RhythmStart\")\n            if evStart then\n                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)\n                    if not alive() then return end\n                    Rhy.Config = cfg\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    Rhy.Stats = { hit = 0, spam = 0 }\n                    Rhy.NextPress = {}\n                    if Rhy.Enabled then\n                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)\n                        NexusLib:Notify({\n                            Title = \"Auto Nameless\",\n                            Message = \"Nameless started [\" .. tostring(Rhy.Mode) .. \"]\" .. (hp and (\" | HP \" .. tostring(hp)) or \"\"),\n                            Duration = 3,\n                        })\n                        if Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                    end\n                end)\n            end\n            local evStop = Events:FindFirstChild(\"RhythmStop\")\n            if evStop then\n                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                end)\n            end\n        end)\n\n        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().\n        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.\n        pcall(function()\n            local evBGM = Events:FindFirstChild(\"BossPhaseBGM\")\n            if evBGM then\n                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)\n                    if not alive() then return end\n                    if bossName ~= nil and tostring(bossName) ~= \"Nameless Octoparasite\" then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Nameless boss signal [\" .. tostring(Rhy.Mode) .. \"]\", Duration = 3 })\n                    end\n                end)\n            end\n            local evP2 = Events:FindFirstChild(\"BossPhase2Setup\")\n            if evP2 then\n                runtimeEnv.NexusNamelessP2 = evP2.OnClientEvent:Connect(function()\n                    if not alive() then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Nameless phase 2 [\" .. tostring(Rhy.Mode) .. \"]\", Duration = 3 })\n                    end\n                end)\n            end\n        end)\n\n\n        runtimeEnv.NexusRhyLoop = RunService.Heartbeat:Connect(function()\n            if not alive() or not Rhy.Enabled then return end\n            local now = tick()\n            Rhy.Active = rhyUiActive() or now < (Rhy.SignalUntil or 0)\n            if not Rhy.Active then return end\n            if Rhy.Mode == \"Risk\" then rhyStartRisk() end\n            rhyScan(now)\n        end)\n\n        local NamelessSection = FarmingTab:CreateSection(\"Auto Nameless Octoparasite\")\n        NamelessSection:CreateButton({\n            Name = \"Teleport to Nameless Octoparasite\",\n            Callback = function() pcall(rhyTeleportToNameless) end\n        })\n        Cfg.register(NamelessSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Nameless\", {\n            Name = \"Auto Nameless\",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Enabled [\" .. tostring(Rhy.Mode) .. \"]. Waiting for Nameless signal from server.\", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Disabled | hit \" .. tostring(Rhy.Stats.hit) .. \" | remote \" .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })), \"Toggle\", \"Auto Nameless\", {\n            Name = \"Auto Nameless\",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Enabled [\" .. tostring(Rhy.Mode) .. \"]. Waiting for Nameless signal from server.\", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Disabled | hit \" .. tostring(Rhy.Stats.hit) .. \" | remote \" .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })\n    end\n\n    -- ===== FAVORITES =====\n    do\n        local FavSection = FarmingTab:CreateSection(\"Auto Favorite Fish\")\n        local allFishNames = {}\n        pcall(function()\n            local rarityModule = require(Info.FishingAreaRarity)\n            if type(rarityModule) == \"table\" then\n                for _, fishTable in pairs(rarityModule) do\n                    if type(fishTable) == \"table\" then\n                        for fishName in pairs(fishTable) do\n                            if type(fishName) == \"string\" and fishName ~= \"\" then\n                                table.insert(allFishNames, fishName)\n                            end\n                        end\n                    end\n                end\n            end\n        end)\n        local uniqueFish = {}\n        for _, name in ipairs(allFishNames) do uniqueFish[name] = true end\n        local fishOptions = {}\n        for name in pairs(uniqueFish) do table.insert(fishOptions, name) end\n        table.sort(fishOptions)\n\n        local fishDropdown = Cfg.register(FavSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Select fish to auto-favourite\", {\n            Name = \"Select fish to auto-favourite\",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })), \"MultiDropdown\", \"Select fish to auto-favourite\", {\n            Name = \"Select fish to auto-favourite\",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })\n\n        local autoFavToggle = Cfg.register(FavSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Favourite Fishes\", {\n            Name = \"Auto Favourite Fishes\",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild(\"FavoriteItem\")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"FavoriteItem remote not found!\", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == \"function\" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild(\"Inventory\")\n                                if not inventory then return end\n                                local selected = NexusState.favorites.selectedFish or {}\n                                if #selected == 0 then return end\n                                local selectedSet = {}\n                                for _, name in ipairs(selected) do selectedSet[name] = true end\n                                for _, item in pairs(inventory:GetChildren()) do\n                                    local fullName = item.Name\n                                    if not string.find(fullName, \"| Favorite$\") then\n                                        local fishName = fullName:match(\"^(.-)%s*|\") or fullName\n                                        if selectedSet[fishName] then\n                                            favoriteEvent:FireServer(fullName)\n                                        end\n                                    end\n                                end\n                            end)\n                            task.wait(0.3)\n                        end\n                    end)\n                    NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"Enabled - scanning every 0.3s\", Duration = 2 })\n                else\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"Disabled\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Favourite Fishes\", {\n            Name = \"Auto Favourite Fishes\",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild(\"FavoriteItem\")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"FavoriteItem remote not found!\", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == \"function\" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild(\"Inventory\")\n            if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })\n\n        -- ===== AUTO FARM CA 2M+ KG =====\n        NexusState.autoFarm2MRunning = false\n        NexusState.autoFarm2MThread = nil\n\n        local function findBigKgIsland()\n            local best, bestKg = nil, 0\n            pcall(function()\n                local rarity = Info:FindFirstChild(\"FishingAreaRarity\")\n                if not rarity then return end\n                for _, area in pairs(rarity:GetChildren()) do\n                    local maxKg = area:FindFirstChild(\"MaxKg\")\n                    local v = maxKg and tonumber(maxKg.Value) or 0\n                    if v >= 2000000 and v > bestKg then\n                        bestKg = v\n                        best = area.Name\n                    end\n                end\n            end)\n            return best, bestKg\n        end\n\n        Cfg.register(GiveSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm 2M+ kg Fish\", {\n            Name = \"Auto Farm 2M+ kg Fish\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoFarm2MRunning = value\n                if NexusState.autoFarm2MThread then\n                    pcall(task.cancel, NexusState.autoFarm2MThread)\n                    NexusState.autoFarm2MThread = nil\n                end\n                if not value then return end\n\n                local islandName, kg = findBigKgIsland()\n                if islandName then\n                    for _, isl in ipairs(NexusState.islands) do\n                        if isl.name == islandName then\n                            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            if root then pcall(function() root.CFrame = isl.cframe end) end\n                            break\n                        end\n                    end\n                    NexusLib:Notify({\n                        Title = \"Auto Farm 2M+\",\n                        Message = \"Farming at \" .. islandName .. \" (max \" .. tostring(kg) .. \" kg)\",\n                        Duration = 3\n                    })\n                else\n                    NexusLib:Notify({ Title = \"Auto Farm 2M+\", Message = \"No 2M+ zone found, farming here.\", Duration = 3 })\n                end\n\n                NexusState.autoFarm2MThread = task.spawn(function()\n                    while NexusState.autoFarm2MRunning do\n                        pcall(function()\n                            local c = LocalPlayer.Character\n                            if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })), \"Toggle\", \"Auto Farm 2M+ kg Fish\", {\n            Name = \"Auto Farm 2M+ kg Fish\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoFarm2MRunning = value\n                if NexusState.autoFarm2MThread then\n                    pcall(task.cancel, NexusState.autoFarm2MThread)\n                    NexusState.autoFarm2MThread = nil\n                end\n                if not value then return end\n\n                local islandName, kg = findBigKgIsland()\n                if islandName then\n                    for _, isl in ipairs(NexusState.islands) do\n                        if isl.name == islandName then\n                            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            if root then pcall(function() root.CFrame = isl.cframe end) end\n                            break\n                        end\n                    end\n                    NexusLib:Notify({\n                        Title = \"Auto Farm 2M+\",\n                        Message = \"Farming at \" .. islandName .. \" (max \" .. tostring(kg) .. \" kg)\",\n                        Duration = 3\n                    })\n                else\n                    NexusLib:Notify({ Title = \"Auto Farm 2M+\", Message = \"No 2M+ zone found, farming here.\", Duration = 3 })\n                end\n\n                NexusState.autoFarm2MThread = task.spawn(function()\n                    while NexusState.autoFarm2MRunning do\n                        pcall(function()\n                            local c = LocalPlayer.Character\n                            if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })\n    end\n\n    local weatherIslands = {\n        [\"foggy\"] = \"Island 7\", [\"blazing sun\"] = \"Island 8\", [\"snowy\"] = \"Island 6\",\n        [\"windy\"] = \"Island 5\", [\"rainy\"] = \"Island 3\", [\"thunderstorm\"] = \"Island 2\"\n    }\n\n    local function getCurrentWeather()\n        local info = MainGui:FindFirstChild(\"Info\")\n        if info then\n            local infoFrame = info:FindFirstChild(\"Info\")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild(\"Value\")\n                    if val and typeof(val) == \"Instance\" then\n                        local text = ((typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value))\n                        return text:gsub(\"Weather:%s*\", \"\")\n                    end\n                end\n            end\n        end\n        return \"Clear\"\n    end\n\n    TPSection:CreateButton({\n        Name = \"Teleport To Current Weather\",\n        Callback = function()\n            local currentWeather = getCurrentWeather()\n            if currentWeather:lower() == \"clear\" or currentWeather == \"\" then\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Server weather is Clear, no event to TP!\", Duration = 3 })\n                return\n            end\n            local targetIslandName = weatherIslands[currentWeather:lower()]\n            if targetIslandName then\n                for _, v in ipairs(NexusState.islands) do\n                    if v.name:lower() == targetIslandName:lower() then\n                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                        if hrp then\n                            hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                            NexusLib:Notify({ Title = \"Weather TP\", Message = \"Teleported to \" .. targetIslandName .. \" for \" .. currentWeather, Duration = 4 })\n                        end\n                        return\n                    end\n                end\n            else\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Unknown weather island mapping for: \" .. currentWeather, Duration = 4 })\n            end\n        end\n    })\n\n    -- Server\n    do\n        local ServerSection = TeleportTab:CreateSection(\"Server\", \"Left\")\n        local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n        local function b64decode(data)\n            data = string.gsub(data, '[^'..b64chars..'=]', '')\n            return (data:gsub('.', function(x)\n                if (x == '=') then return '' end\n                local r,f='',(b64chars:find(x, 1, true)-1)\n                for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end\n                return r;\n            end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)\n                if (#x ~= 8) then return '' end\n                local c=0\n                for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end\n                return string.char(c)\n            end))\n        end\n\n        local savedJobId = \"\"\n        local lastHopAt = 0\n        ServerSection:CreateTextbox({\n            Name = \"Join by Job ID\",\n            Placeholder = \"Paste Job ID here...\",\n            Default = \"\",\n            Callback = function(text)\n                if text and text ~= \"\" then\n                    local finalJobId = text\n                    local matchB64 = string.match(text, \"NEXUSHUB|([^%s]+)\")\n                    if matchB64 then\n                        local success, decoded = pcall(b64decode, matchB64)\n                        if success and decoded and decoded ~= \"\" then\n                            finalJobId = decoded\n                        end\n                    end\n                    if finalJobId == game.JobId then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Already in this server.\", Duration = 3 })\n                        return\n                    end\n                    if tick() - lastHopAt < 30 then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Hop cooldown, try again shortly.\", Duration = 3 })\n                        return\n                    end\n                    lastHopAt = tick()\n                    savedJobId = finalJobId\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Joining server...\", Duration = 3 })\n                    Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, finalJobId, LocalPlayer)\n                end\n            end\n        })\n        ServerSection:CreateButton({\n            Name = \"Delete Job ID\",\n            Callback = function()\n                savedJobId = \"\"\n                NexusLib:Notify({ Title = \"Server Hop\", Message = \"Job ID cleared!\", Duration = 2 })\n            end\n        })\n    end\n\n    -- Islands\n    do\n        local IslandSection = TeleportTab:CreateSection(\"Islands\", \"Right\")\n        for _, v in ipairs(NexusState.islands) do\n            IslandSection:CreateButton({\n                Name = v.name,\n                Callback = function()\n                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                        NexusLib:Notify({ Title = \"Teleport\", Message = \"Teleported to \" .. v.name, Duration = 3 })\n                    end\n                end\n            })\n        end\n    end\n    -- ===== PLAYERS SECTION =====\n    do\n        local PlayerSection = TeleportTab:CreateSection(\"Players\", \"Right\")\n        \n        local selectedPlayer = nil\n        local playerDropdown = nil  -- Keep a reference to the dropdown\n        local playerList = {}\n        \n        -- List refresh helper\n        local function refreshPlayerList()\n            -- Read the player list\n            playerList = {}\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    table.insert(playerList, player.Name)\n                end\n            end\n            if #playerList == 0 then\n                table.insert(playerList, \"No other players\")\n                selectedPlayer = \"No other players\"\nNexusPremiumKey.txt@nexus_embedded_GET_KEY_URLGothamBoldSubmit KeyFREEMIUMGet KeyMethod\x0F\xC0\x10\x07I\x93\xC9\x07U\x19a\x00newKey\xCC\x07\xD0\x0F0\x08\x11\x07",
